#!/usr/bin/env python3
"""Deploy dnc_supabase_initial_load (generated by build_supabase_sync.py) as a NEW live n8n
workflow. First deploy -- no safe_patch_workflow needed yet (nothing live to diff against)."""
import json
import os
import ssl
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
ENV_PATH = os.path.join(os.path.dirname(HERE), ".env")
for line in open(ENV_PATH, encoding="utf-8"):
    line = line.strip()
    if line and not line.startswith("#") and "=" in line:
        k, v = line.split("=", 1)
        os.environ.setdefault(k, v)
BASE = os.environ["N8N_BASE_URL"].rstrip("/")
KEY = os.environ["N8N_API_KEY"]
CA = os.environ.get("REQUESTS_CA_BUNDLE")
ctx = ssl.create_default_context(cafile=CA) if CA and os.path.exists(CA) else None


def n8n(path, method="GET", body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(BASE + path, method=method, data=data,
                                headers={"X-N8N-API-KEY": KEY, "Content-Type": "application/json",
                                         "accept": "application/json"})
    with urllib.request.urlopen(r, timeout=180, context=ctx) as x:
        return json.load(x) if x.length != 0 else {}


def main():
    with open(os.path.join(HERE, "workflows", "dnc_supabase_initial_load",
                            "dnc_supabase_initial_load.json"), encoding="utf-8") as f:
        wf_json = json.load(f)
    created = n8n("/api/v1/workflows", "POST",
                  {"name": wf_json["name"], "nodes": wf_json["nodes"],
                   "connections": wf_json["connections"], "settings": wf_json["settings"]})
    wid = created["id"]
    n8n(f"/api/v1/workflows/{wid}/activate", "POST", {})
    print(f"deployed dnc_supabase_initial_load, id={wid}, active=True")
    with open(os.path.join(HERE, "DEPLOYED_WORKFLOW_ID.txt"), "w") as f:
        f.write(wid)


if __name__ == "__main__":
    main()
